import { InspectorControls, useBlockProps } from '@wordpress/block-editor';
import {
    FormTokenField,
    PanelBody,
    PanelRow,
    SelectControl,
    TextControl,
    ToggleControl
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import ServerSideRender from '@wordpress/server-side-render';
import './editor.scss';

export default function Edit( { attributes, setAttributes } ) {
    const {
        meta_box_id,
        ajax,
        allow_scroll,
        edit,
        allow_delete,
        force_delete,
        show_add_more,
        post_type,
        post_id,
        post_status,
        post_fields,
        label_title,
        label_content,
        label_excerpt,
        label_date,
        label_thumbnail,
        submit_button,
        add_button,
        delete_button,
        redirect,
        confirmation,
        delete_confirmation,
        recaptcha_key,
        recaptcha_secret,
    } = attributes;

    let post_types = Object.keys( mbfsData.post_types ).map( post_type => {
        return {
            label: post_type,
            value: post_type
        };
    } );
    let post_statuses = Object.keys( mbfsData.post_statuses ).map( post_status => {
        return {
            label: post_status,
            value: post_status
        };
    } );
    return (
        <div { ...useBlockProps() }>
            <InspectorControls>
                <PanelBody className="mbfs-block" title={ __( 'Settings', 'mb-frontend-submission' ) }>
                    <PanelRow>
                        <TextControl
                            label={ __( 'ID', 'mb-frontend-submission' ) }
                            help={ __( 'Field group ID(s). If multiple field groups, enter their IDs separated by commas. Optional.', 'mb-frontend-submission' ) }
                            value={ meta_box_id }
                            onChange={ ( value ) => setAttributes( { meta_box_id: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Enable ajax submission', 'mb-frontend-submission' ) }
                            checked={ ajax }
                            onChange={ () => setAttributes( { ajax: !ajax } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Allow scroll', 'mb-frontend-submission' ) }
                            help={ __( 'Enable scroll to message after ajax submission.', 'mb-frontend-submission' ) }
                            checked={ allow_scroll }
                            onChange={ () => setAttributes( { allow_scroll: !allow_scroll } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Edit', 'mb-frontend-submission' ) }
                            help={ __( 'Allow users to edit the post after submitting. If enabled, then ajax submission will be disabled.', 'mb-frontend-submission' ) }
                            checked={ edit }
                            onChange={ () => setAttributes( { edit: !edit } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Allow delete', 'mb-frontend-submission' ) }
                            help={ __( 'Allow users to delete the submitted post.', 'mb-frontend-submission' ) }
                            checked={ allow_delete }
                            onChange={ () => setAttributes( { allow_delete: !allow_delete } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Force delete', 'mb-frontend-submission' ) }
                            help={ __( 'Whether to delete the submitted post permanently or temporarily (move to Trash).', 'mb-frontend-submission' ) }
                            checked={ force_delete }
                            onChange={ () => setAttributes( { force_delete: !force_delete } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <ToggleControl
                            label={ __( 'Show add more', 'mb-frontend-submission' ) }
                            help={ __( 'Show add new button after submit.', 'mb-frontend-submission' ) }
                            checked={ show_add_more }
                            onChange={ () => setAttributes( { show_add_more: !show_add_more } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <SelectControl
                            label={ __( 'Post type', 'mb-frontend-submission' ) }
                            help={ __( 'The submitted post type. Default is the first post type defined in the meta box. If meta box is made for multiple post types, you should set this attribute to the correct one.', 'mb-frontend-submission' ) }
                            value={ post_type }
                            options={ [
                                { label: __( '-- Choose Post Type --', 'mb-frontend-submission' ), value: '' },
                                ...post_types
                            ] }
                            onChange={ ( value ) => setAttributes( { post_type: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Post ID', 'mb-frontend-submission' ) }
                            help={ __( 'The post ID. Used when you want to update an existing post. If you want to pass the ID of the current post, set it to "current".', 'mb-frontend-submission' ) }
                            value={ post_id }
                            onChange={ ( value ) => setAttributes( { post_id: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <SelectControl
                            label={ __( 'Post status', 'mb-frontend-submission' ) }
                            help={ __( 'The status for submitted posts.', 'mb-frontend-submission' ) }
                            value={ post_status }
                            options={ [
                                { label: __( '-- Choose Post Status --', 'mb-frontend-submission' ), value: '' },
                                ...post_statuses
                            ] }
                            onChange={ ( value ) => setAttributes( { post_status: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <FormTokenField
                            __experimentalAutoSelectFirstMatch
                            __experimentalExpandOnFocus
                            label={ __( 'Post Fields', 'mb-frontend-submission' ) }
                            help={ __( 'List of post fields you want to show in the frontend.', 'mb-frontend-submission' ) }
                            value={ post_fields }
                            suggestions={ [
                                'title',
                                'content',
                                'excerpt',
                                'date',
                                'thumbnail'
                            ] }
                            onChange={ ( value ) => setAttributes( { post_fields: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Title field label', 'mb-frontend-submission' ) }
                            value={ label_title }
                            onChange={ ( value ) => setAttributes( { label_title: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Content field label', 'mb-frontend-submission' ) }
                            value={ label_content }
                            onChange={ ( value ) => setAttributes( { label_content: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Excerpt field label', 'mb-frontend-submission' ) }
                            value={ label_excerpt }
                            onChange={ ( value ) => setAttributes( { label_excerpt: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Date field label', 'mb-frontend-submission' ) }
                            value={ label_date }
                            onChange={ ( value ) => setAttributes( { label_date: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Thumbnail field label', 'mb-frontend-submission' ) }
                            value={ label_thumbnail }
                            onChange={ ( value ) => setAttributes( { label_thumbnail: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Submit button text', 'mb-frontend-submission' ) }
                            help={ __( 'The submit button text.', 'mb-frontend-submission' ) }
                            value={ submit_button }
                            onChange={ ( value ) => setAttributes( { submit_button: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Add new button text', 'mb-frontend-submission' ) }
                            value={ add_button }
                            onChange={ ( value ) => setAttributes( { add_button: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Delete button text', 'mb-frontend-submission' ) }
                            value={ delete_button }
                            onChange={ ( value ) => setAttributes( { delete_button: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Custom redirect URL', 'mb-frontend-submission' ) }
                            value={ redirect }
                            onChange={ ( value ) => setAttributes( { redirect: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Confirmation text', 'mb-frontend-submission' ) }
                            help={ __( 'The text for the confirmation message when the form is successfully submitted.', 'mb-frontend-submission' ) }
                            value={ confirmation }
                            onChange={ ( value ) => setAttributes( { confirmation: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Delete confirmation text', 'mb-frontend-submission' ) }
                            help={ __( 'The text for the confirmation message when the post is deleted.', 'mb-frontend-submission' ) }
                            value={ delete_confirmation }
                            onChange={ ( value ) => setAttributes( { delete_confirmation: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Recaptcha key', 'mb-frontend-submission' ) }
                            help={ __( 'Google reCaptcha site key (version 3).', 'mb-frontend-submission' ) }
                            value={ recaptcha_key }
                            onChange={ ( value ) => setAttributes( { recaptcha_key: value } ) }
                        />
                    </PanelRow>
                    <PanelRow>
                        <TextControl
                            label={ __( 'Recaptcha secret', 'mb-frontend-submission' ) }
                            help={ __( 'Google reCaptcha secret key (version 3).', 'mb-frontend-submission' ) }
                            value={ recaptcha_secret }
                            onChange={ ( value ) => setAttributes( { recaptcha_secret: value } ) }
                        />
                    </PanelRow>
                </PanelBody>
            </InspectorControls>
            <ServerSideRender
                block="meta-box/submission-form"
                attributes={ attributes }
            />
        </div>
    );
}
